    card_no_read: "Można grać bez czytania",
    history_title: "Biblioteka historii gier",
    history_intro: "Każda gra w tej kolekcji ma swoją własną historię – niektóre liczą sobie ponad pięć tysięcy lat, inne zaledwie dekadę. Przeczytaj je tutaj, mniej więcej w kolejności, w jakiej się pojawiły, albo przejdź od razu do pełnej historii wybranej gry.",
    history_dates_note: "Daty najstarszych gier są przybliżone – ich dokładne pochodzenie często ginie w mrokach historii lub jest przedmiotem sporów historyków.",
    history_read_more: "Pełna historia →",
    home_history_title: "Ciekawi Cię, skąd wzięły się te gry?",
    home_history_desc: "Przeczytaj historię powstania każdej gry, od starożytnego Egiptu po ostatnią dekadę – bez przeglądania, tylko historia.",
    home_chess_desc: "Klasyczna gra. Lokalnie dla 2 graczy, z wbudowanym silnikiem albo online przez Lichess.",
    home_go_desc: "Starożytna gra o terytorium. Lokalnie dla 2 graczy albo z wbudowanym silnikiem, trzy rozmiary planszy, trzy poziomy trudności.",
    home_checkers_desc: "Klasyczna gra w bicie i przeskakiwanie pionków. Lokalnie dla 2 graczy albo z wbudowanym silnikiem, trzy poziomy trudności.",
    home_ur_desc: "Licząca 4600 lat gra wyścigowa odkryta na nowo ze starożytnej Mezopotamii. Lokalnie dla 2 graczy albo z wbudowanym silnikiem, z polami rozetowymi i zbijaniem przez wejście na pole.",
    home_morris_desc: "Licząca sobie wieki gra strategiczna polegająca na ustawianiu i przesuwaniu pionków, by tworzyć młynki. Lokalnie dla 2 graczy albo z wbudowanym silnikiem, z klasyczną zasadą \"latania\" w końcówce.",
    home_backgammon_desc: "Klasyczna gra wyścigowa w kości. Lokalnie dla 2 graczy albo z wbudowanym silnikiem, z barem, zbijaniem pojedynczych pionków i wyprowadzaniem bierek z planszy.",
    home_xiangqi_desc: "Chińskie szachy: generałowie, słonie, działa i inne bierki na siatce 9x10. Lokalnie dla 2 graczy albo z wbudowanym silnikiem, z przełącznikiem między tradycyjnymi znakami a symbolami w zachodnim stylu.",
    home_mancala_desc: "Jedna z najstarszych rodzin gier na świecie: rozsiewaj ziarna po planszy, by zapełnić swój własny skarbiec. Lokalnie dla 2 graczy albo z wbudowanym silnikiem, ze zbijaniem i dodatkowymi ruchami.",
    home_reversi_desc: "Odwracaj kolor planszy, okrążając pionki przeciwnika. Lokalnie dla 2 graczy albo z wbudowanym silnikiem.",
