    mahjong_new_game: "Nowa gra",
    mahjong_shuffle: "Przetasuj pozostałe kafelki",
    chess_history_intro: "Od starożytnej indyjskiej gry wojennej do najdokładniej badanej gry planszowej na świecie - szachy przemierzyły kontynenty i stulecia, by stać się tym, czym są dzisiaj.",
    go_history_intro: "Go to jedna z najstarszych gier planszowych wciąż rozgrywanych w swojej pierwotnej formie - gra o terytorium i kamienie, której korzenie w Chinach sięgają prawdopodobnie ponad 2500 lat wstecz.",
    checkers_history_intro: "Warcaby to gra o prostych zasadach i głębokiej strategii, powstała z połączenia starożytnej planszy z nowszym sposobem bicia.",
    ur_history_intro: "Licząca sobie mniej więcej 4600 lat Królewska Gra z Ur to jedna z najstarszych odkrytych gier planszowych - i, dzięki detektywistycznej pracy rozciągniętej na dwa tysiąclecia, jedna z niewielu starożytnych gier, w które wciąż możemy grać według oryginalnych zasad.",
    morris_history_intro: "Niewiele gier wyryto na tylu różnych powierzchniach na przestrzeni tylu stuleci co młynka - od dachów egipskich świątyń po krużganki angielskich katedr.",
    backgammon_history_intro: "Drzewo genealogiczne backgammona przechodzi przez niemal każdą cywilizację, która kiedykolwiek rzucała kośćmi - od starożytnej Mezopotamii i Rzymu po kawiarnie współczesnego Bliskiego Wschodu.",
    xiangqi_history_intro: "Chińskie szachy dzielą głębokie korzenie z szachami międzynarodowymi, a mimo to przeszły przez ponad tysiąc lat własną, odrębną drogą, by stać się grą, w którą dziś gra kilkaset milionów ludzi.",
    mancala_history_intro: "Mancala to nie jedna gra, lecz cała ich rodzina - jedna z najstarszych rodzin gier na Ziemi, zbudowana wokół prostej, uniwersalnej czynności przekładania ziaren lub kamyków między dołkami.",
    reversi_history_intro: "Wiktoriańska gra salonowa, wynaleziona na nowo dwukrotnie w odstępie ponad stulecia.",
    fourinarow_history_intro: "Prosty pomysł napędzany grawitacją, który zmienił się w jedną z najlepiej sprzedających się gier XX wieku.",
    gomoku_history_intro: "Prosta gra w ustawianie kamieni w rzędzie, której właśnie prostota zmusiła graczy turniejowych do zmiany zasad.",
    tictactoe_history_intro: "Chyba najbardziej znana gra na kartce i ołówku – z korzeniami w starożytnym Rzymie i miejscem w historii komputerów.",
    senet_history_intro: "Jedna z najstarszych odnalezionych gier planszowych - i taka, której dokładne zasady zaginęły na tysiące lat.",
    shogi_history_intro: "Japońska odmiana rodziny gier szachowych i jedyny większy wariant, w którym zbita bierka nie opuszcza gry - dołącza do strony, która ją zbiła.",
    sudoku_history_intro: "W przeciwieństwie do każdej innej gry w tym zbiorze, Sudoku nie ma żadnego starożytnego rodowodu - jest ledwie starsze od komputera osobistego.",
    pegsolitaire_history_intro: "Łamigłówka dla jednego gracza, na tyle stara, że ma własną legendę dworską, i temat jednego z bardziej zaskakujących wyników w matematyce rekreacyjnej.",
    minesweeper_history_intro: "Łamigłówka, której definiująca zasada - całkowicie bezpieczny pierwszy ruch - stała się standardem dopiero, gdy to komputery, a nie drukowana strona, mogły wygenerować świeżą planszę na żądanie.",
    nonogram_history_intro: "Łamigłówka logiczna wymyślona dwukrotnie w Japonii mniej więcej w tym samym czasie, niezależnie od siebie - i nazwana od imienia jednej z dwojga jej twórców.",
    twenty48_history_intro: "Gra zbudowana niemal wyłącznie z pomysłów innych gier, stworzona w jeden weekend i sklonowana przez więcej osób niż być może jakakolwiek wcześniejsza gra przeglądarkowa.",
    mahjong_history_intro: "Gra dla jednego gracza polegająca na dopasowywaniu kafelków, nazwana na cześć - i wizualnie zapożyczająca od - zupełnie innej gry dla czterech graczy, z którą nie ma poza tym niemal nic wspólnego.",
    back_home: "← Powrót do strony głównej",
    menu_toggle: "☰ Menu",
