    game_blockers: "Zablokowana droga",
    home_blockers_desc: "Wyścig z kostką do mety na górze planszy dla 2–4 graczy: klocki blokują ścieżki, a kto na klocku stanie, stawia go na drodze innym. Przeciwko komputerowi lub ze znajomymi na jednym urządzeniu.",
    bl_level_label: "Poziom",
    bl_board_aria: "Plansza Zablokowana droga",
    bl_history_intro: "Zablokowana droga to gra wyścigowa PaperGames; nawiązuje do dawnych elementów gier wyścigowych z kostką, takich jak odsyłanie pionków do domu i zagradzanie drogi.",
    quickrules_blockers_1: "Rzuć kostką i przesuń jeden pionek dokładnie o tyle pól po ścieżkach w stronę mety na górze.",
    quickrules_blockers_2: "Żaden pionek nie może przejść przez klocek. Gdy staniesz na klocku, stawiasz go na innym wolnym polu – na drodze kogoś innego.",
    quickrules_blockers_3: "W górnej połowie (okrągłe pola) stanięcie na pionku innego gracza odsyła go do domu; na kwadratowych polach poniżej pionki są bezpieczne. Wygrywa pierwszy pionek na mecie albo, jeśli tak wybrano przed grą, gracz, który pierwszy ma wszystkie pionki na mecie.",
    quickrules_blockers_4: "Plansza „Szybka” (wybierana przed grą): mniejsza, po 4 pionki; na polu odpoczynku (ośmiokąt) pionek jest bezpieczny, mieści się tam tylko jeden pionek i nie można tam postawić klocka.",
