    home_schafkopf_desc: "Bawarska gra karciana dla czterech osób z kartami niemieckimi: ty przeciwko trzem komputerom w Sauspiel, Wenz i Solo, ze Schneider, Schwarz, Laufende i listą punktów. Tylko punkty.",
    sf_history_intro: "Schafkopf wspomniano po raz pierwszy w 1782 roku w Saksonii; pierwsza wyraźnie bawarska gra jest udokumentowana w 1849 roku.",
    quickrules_schafkopf_1: "Pasuj albo zapowiedz grę: Sauspiel (wywołujesz asa, a kto go ma, gra z tobą), Wenz lub Solo.",
    quickrules_schafkopf_2: "Wyżniki i niżniki są wysokimi atutami (w Wenzu tylko niżniki); trzeba dokładać do koloru. Wywołany as musi zostać zagrany, gdy wyjdzie jego kolor.",
    quickrules_schafkopf_3: "Strona grającego potrzebuje 61 ze 120 punktów. Schneider, Schwarz i Laufende podnoszą wynik.",
