    game_canasta: "Canasta",
    home_canasta_desc: "Klasyczna gra typu remik dla dwojga, 108 kart: układy z kart jednej wartości, canasty z siedmiu kart, jokery i dwójki jako dzikie karty, czerwone i czarne trójki. Ty przeciw komputerowi, do 5000 punktów albo krótko do 2000.",
    cn_history_intro: "Canastę wymyślono w 1939 roku w Montevideo w Urugwaju, a w 1949 roku dotarła do Nowego Jorku.",
