    game_bridge: "Bridge",
    home_bridge_desc: "Brydż kontraktowy dla czterech osób: ty i twój partner komputerowy przeciw dwóm komputerom. Prowadzona licytacja przyciskami, dziadek odkryty na stole, zapis Chicago (cztery rozdania) albo robrowy.",
    br_history_intro: "Brydż wywodzi się z wista; pierwsze znane zasady („Biritch, or Russian Whist”) pochodzą z 1886 roku, brydż kontraktowy z 1925.",
    quickrules_bridge_1: "Licytuj, ile lew ponad sześć weźmie twoja strona, w kolorze atutowym lub bez atu; najwyższa odzywka staje się kontraktem.",
