    game_tenpairs: "Pary do dziesięciu",
    home_tenpairs_desc: "Łamigłówka na papierze i ołówek polegająca na skreślaniu cyfr: pary równe lub dające razem 10, które się widzą. Utknąłeś? Dopisz pozostałe cyfry. Klasyczny start albo losowy, trzy poziomy.",
    tp_history_intro: "Łamigłówka na papierze ze szkolnych zeszytów; jej pochodzenie nie jest udokumentowane.",
    quickrules_tenpairs_1: "Dotknij dwóch cyfr równych (3 i 3) albo dających razem 10 (3 i 7), aby je skreślić.",
    quickrules_tenpairs_2: "Muszą się widzieć: obok siebie w poziomie, w pionie lub po skosie albo z samymi skreślonymi polami między nimi; w poziomie także przez koniec wiersza.",
    quickrules_tenpairs_3: "Utknąłeś? Dotknij Dopisz: pozostałe cyfry zostaną dopisane na końcu (najwyżej 5 razy). Skreśl wszystkie cyfry, aby wygrać.",
