    game_mathcross: "Siatka działań",
    home_mathcross_desc: "Wpisz liczby od 1 do 9, każdą raz, tak aby każdy wiersz i każda kolumna się zgadzały - liczymy od lewej do prawej. Trzy poziomy, zawsze dokładnie jedno rozwiązanie, bez zgadywania.",
    mc_history_intro: "Łamigłówka z działaniami w wierszach i kolumnach, spokrewniona ze starożytnym kwadratem magicznym z liczb od 1 do 9.",
    quickrules_mathcross_1: "Wpisz liczby od 1 do 9 w kratki, każdą dokładnie raz.",
    quickrules_mathcross_2: "Każdy wiersz i każda kolumna musi dawać swój wynik. Liczymy od lewej do prawej (z góry na dół), bez pierwszeństwa mnożenia: 3 + 4 × 2 = 14.",
    quickrules_mathcross_3: "Dotknij kratki, a potem liczby. Ptaszek lub krzyżyk pokazuje, czy pełny wiersz lub kolumna się zgadza.",
    game_cardduel: "Pojedynek kart",
    home_cardduel_desc: "Fantastyczna gra karciana dla dwóch magów: istoty i czary, cztery gotowe talie lasu, ognia, wody i kamienia. Przeciw komputerowi na trzech poziomach albo we dwoje na jednym urządzeniu.",
    quickrules_cardduel_1: "Sprowadź maga przeciwnika z 20 punktów życia do 0.",
    quickrules_cardduel_2: "Co turę masz 1 mocy więcej (do 10). Dotknij karty, a potem Zagraj: istoty zostają na stole, czary działają raz.",
    quickrules_cardduel_3: "Aby zaatakować, dotknij gotowej istoty (gruba ramka), a potem celu. Bastion trzeba zaatakować najpierw.",
