    home_villains_desc: "Każdy gra złoczyńcą z baśni braci Grimm z własnym celem – wiedźmą, wilkiem, Titeliturym i innymi – a pozostali stawiają mu na drodze bohaterów. Od 2 do 4 graczy, przeciw komputerowi albo na jednym urządzeniu.",
