    home_forestvillage_desc: "Leśne zwierzęta zbierają glinę, nasiona i pióra, wysyłają pracowników i budują własną osadę. Pasujące zwierzę obniża koszt budynku o jedno pióro. 1–4 graczy, solo lub przeciw komputerowi.",
