    ab_item_silverbook: "Srebrna księga",
    ab_item_goldenseed: "Złote nasiono",
    ab_room_cave_1: "Woda kapie z sufitu do małej, czystej sadzawki.",
    ab_room_cave_2: "Ze ścian wyrastają niebieskie kryształy i łagodnie świecą.",
    ab_room_cave_3: "Wąskie przejście. Musisz schylić się pod niską skałą.",
    ab_room_cave_4: "Stare wózki górnicze stoją na zardzewiałych szynach. Dawno temu ktoś tu pracował.",
    ab_room_cave_5: "Jaskinia otwiera się w wysoką salę. Twoje kroki odbijają się echem.",
    ab_room_cave_6: "Podłogę pokrywa błyszczący piasek. Chrzęści pod butami.",
    ab_room_cave_7: "Ze szczeliny w skale wieje zimny wiatr.",
    ab_room_cave_8: "Rosną tu grzyby wielkie jak krzesła. Pachną ziemią.",
    ab_room_cave_9: "Podziemny strumień szumi w kamiennym korycie.",
    ab_room_cave_10: "Jedną ścianę pokrywają dziwne rysunki gwiazd.",
    ab_room_cave_11: "Stalaktyty zwisają z sufitu jak kamienne sople.",
    ab_room_cave_12: "Mała boczna jaskinia. Ktoś zostawił tu stary koc.",
    ab_room_cave_13: "Ścieżka wspina się po gładkich skałach, śliskich od mchu.",
    ab_room_cave_14: "W ciemnym kącie śpią nietoperze. Idziesz na palcach.",
    ab_room_cave_15: "Okrągła komnata z gładką, jakby wypolerowaną podłogą.",
    ab_room_cave_16: "Zielony mech oświetla ściany bladym blaskiem.",
    ab_room_cave_17: "Kiedyś był tu most linowy. Zostały tylko słupki.",
    ab_room_cave_18: "Powietrze jest tu ciepłe. Gdzieś głęboko w dole coś dudni.",
    ab_room_cave_19: "Wszędzie leżą odłamki kryształu, jakby pękł wielki kamień.",
    ab_room_cave_20: "Cichy zakątek. Twoja lampa rzuca długie cienie.",
    ab_room_tower_1: "Regały pełne zakurzonych książek sięgają sufitu.",
    ab_room_tower_2: "Kręte schody wiją się w górę. Stopnie skrzypią.",
    ab_room_tower_3: "Kruki siedzą na belce i patrzą na ciebie błyszczącymi oczami.",
    ab_room_tower_4: "Stara kuchnia. Nad zimnym paleniskiem wisi kocioł.",
    ab_room_tower_5: "Przez okrągłe okno widzisz las daleko w dole.",
    ab_room_tower_6: "Gabinet z ogromnym biurkiem. Atrament wysechł w kałamarzach.",
    ab_room_tower_7: "Za szklaną ścianą powoli obracają się zębatki. Tik, tak.",
    ab_room_tower_8: "Długi korytarz z portretami. Ich oczy jakby za tobą wodzą.",
    ab_room_tower_9: "Pokój pełen map. Jedna z nich pokazuje wieżę taką jak ta.",
    ab_room_tower_10: "Na stole palą się świece, choć nikogo tu chyba nie ma.",
    ab_room_tower_11: "Spiżarnia ze słojami suszonych ziół i kolorowych proszków.",
    ab_room_tower_12: "Wiatr gwiżdże przez połamaną okiennicę.",
    ab_room_tower_13: "Pokój muzyczny. Harfa sama gra jeden dźwięk.",
    ab_room_tower_14: "Wąska kładka z desek prowadzi od jednej ściany do drugiej.",
    ab_room_tower_15: "Sypialnia z łóżkiem z baldachimem. Zasłony są pełne dziur.",
    ab_room_tower_16: "Pracownia z lunetą skierowaną w niebo.",
    ab_room_tower_17: "Czarne pióra leżą na całej podłodze.",
    ab_room_tower_18: "Na ścianie wisi lustro, ale pokazuje inny pokój.",
    ab_room_tower_19: "Mały balkon. Tu na górze wiatr pachnie deszczem.",
    ab_room_tower_20: "Chłodna sala z podłogą z czarnych i białych płytek.",
    ab_room_forest_1: "Mgła wisi między drzewami. Ledwie widzisz własną rękę.",
    ab_room_forest_2: "Polana pełna kwiatów. Pszczoły brzęczą w słońcu.",
    ab_room_forest_3: "Stara ścieżka zarośnięta paprociami.",
    ab_room_forest_4: "Dziuplaste drzewo, tak duże, że można w nim stanąć.",
    ab_room_forest_5: "Mały staw. Żaby skaczą do wody, gdy nadchodzisz.",
    ab_room_forest_6: "Korzenie grube jak ręce przecinają ścieżkę.",
    ab_room_forest_7: "Wysoko w koronach drzew śpiewają ptaki.",
    ab_room_forest_8: "W trawie leży krąg z białych kamieni.",
    ab_room_forest_9: "Krzaki jeżyn rosną wzdłuż kamiennego muru.",
    ab_room_forest_10: "Ziemia jest miękka i zielona od mchu. Panuje cisza.",
    ab_room_forest_11: "Zwalony pień leży nad parowem jak most.",
    ab_room_forest_12: "Opuszczona chata. Drzwi są otwarte.",
    ab_room_forest_13: "Wysokie sosny skrzypią na wietrze.",
    ab_room_forest_14: "Małe światełka tańczą nad bagnem.",
    ab_room_forest_15: "Ogromny dąb z twarzą wyrzeźbioną w korze.",
    ab_room_forest_16: "Grzyby rosną w idealnym kręgu.",
    ab_room_forest_17: "Strumyk szemrze po gładkich kamykach.",
    ab_room_forest_18: "Ciemny gąszcz. Gałęzie drapią cię po rękawach.",
    ab_room_forest_19: "Słoneczne wzgórze. Stąd mgła w dole wygląda jak morze.",
    ab_room_forest_20: "Stare kamienne stopnie prowadzą między dwiema brzozami.",
    home_adventurebook_desc: "Gra fabularna dla jednej osoby: stwórz bohatera, zwiedzaj komnata po komnacie jaskinię, wieżę lub las, rzucaj kośćmi w próbach i walkach i przynieś zaginiony skarb. Łatwy, Średni lub Trudny.",
    quickrules_adventurebook_1: "Stwórz bohatera, potem znajdź skarb tego miejsca i przynieś go do wejścia.",
    quickrules_adventurebook_2: "Próby: dwie kości plus wartość muszą osiągnąć podaną liczbę. Wynik pokazuje się z rachunkiem.",
    quickrules_adventurebook_3: "Walki toczą się w rundach: atak, obrona, przedmiot, umiejętność klasy albo ucieczka. Gra zapisuje po każdym kroku.",
