    game_differences: "Znajdź różnice",
    home_differences_desc: "Dwa obrazki, które różnią się w 3, 5 lub 7 miejscach: czegoś brakuje, ma inny wzór, jest odbite lub przesunięte. Dotknij różnicy na jednym z obrazków. Bez pośpiechu, z podpowiedzią, gdy utkniesz. Albo wyszukiwanka: znajdź od 5 do 10 rzeczy na dużym obrazku pomieszczenia - kuchni, strychu, ogrodu i dziewięciu innych.",
    df_history_intro: "Łamigłówka znana z gazet, czasopism dla dzieci i zeszytów z zagadkami; kiedy i gdzie pojawiła się po raz pierwszy, nie jest wiarygodnie udokumentowane.",
