    game_pentomino: "Układanka pentomino",
    home_pentomino_desc: "Ułóż dwanaście klocków z pięciu kwadratów w prostokąt - obracanie i odbijanie dotknięciem, bez przeciągania. Swobodne układanie w czterech rozmiarach albo z podanymi klockami startowymi i dokładnie jednym rozwiązaniem.",
    pt_history_intro: "Dwanaście klocków z pięciu kwadratów każdy: łamigłówka opublikowana przez Henry'ego Dudeneya w 1907 roku, nazwana „pentomino” przez Solomona Golomba w 1953 roku.",
    quickrules_pentomino_1: "Wypełnij prostokąt klockami; każde pole zostaje zakryte dokładnie raz.",
    quickrules_pentomino_2: "Wybierz klocek pod planszą, obróć go lub odbij, a potem dotknij pola, na które ma trafić jego kropka. Dotknij położonego klocka, aby go znowu podnieść.",
    quickrules_pentomino_3: "W trybie „Podane klocki startowe” niektóre klocki leżą na stałe, a pozostałe pasują tylko w jeden sposób.",
    pt_mode_label: "Tryb:",
    pt_mode_free: "Swobodne układanie",
