    msg_pt_choose: "Wybierz klocek pod planszą.",
    msg_pt_place: "W razie potrzeby obróć go lub odbij, a potem dotknij miejsca, na które ma trafić jego kropka.",
    msg_pt_nofit: "Klocek tam nie pasuje.",
    msg_pt_fixed: "Ten klocek jest stały.",
    msg_t_pt_picked: "Podniesiono klocek {s}.",
    msg_pt_won: "Prostokąt jest pełny - rozwiązane!",
    msg_t_pt_hint_place: "Podpowiedź: klocek {s} pasuje w zaznaczone miejsce.",
    msg_t_pt_hint_remove: "Podpowiedź: klocek {s} blokuje rozwiązanie - zdejmij go.",
