    msg_t_pt_info: "Położone: {n} z {m} klocków",
    game_arrows: "Strzałki",
    home_arrows_desc: "Dotknij strzałki, a wysunie się z planszy - jeśli żadna inna strzałka nie stoi jej na drodze. Oczyść całą planszę; każda łamigłówka ma rozwiązanie, z cofaniem, podpowiedziami i bez limitu czasu. Na poziomach Trudny i Mistrz zablokowane strzałki suną do przodu i mogą utknąć.",
    aw_history_intro: "Elementy, które mogą się przesuwać tylko w jedną stronę, są krewnymi łamigłówek przesuwnych, które w 1880 roku stały się szałem; wersja ze strzałkami to młoda łamigłówka.",
    quickrules_arrows_1: "Dotknij strzałki: opuszcza planszę w swoim kierunku, jeśli droga do krawędzi jest wolna.",
    quickrules_arrows_2: "Jeśli na drodze stoi inna strzałka, nic się nie dzieje - najpierw usuń tamtą. Na poziomach Trudny i Mistrz sunie za to aż do tamtej strzałki.",
    quickrules_arrows_3: "Oczyść całą planszę. Każda łamigłówka ma rozwiązanie; „Podpowiedź” zaznacza strzałkę, która może wyjść.",
