    tg_level_outline: "Tylko kontur",
    game_loosen: "Rozepnij pierścienie",
    home_loosen_desc: "Pierścienie zaczepione o siebie, każdy z przerwą: obracaj je - zaczepione pierścienie obracają się w drugą stronę - aż uwolnią się jeden po drugim. Trzy poziomy, z najmniejszą liczbą ruchów, cofaniem i podpowiedziami.",
    lr_history_intro: "Łamigłówki z pierścieniami są stare - chińskie pierścienie opisywano już około 1500 roku; ta płaska wersja z przerwami jest nowa.",
    quickrules_loosen_1: "Dotknij pierścienia: obraca się o ćwierć obrotu zgodnie z ruchem wskazówek zegara, a zaczepione o niego obracają się w drugą stronę.",
    quickrules_loosen_2: "Pierścień jest wolny, gdy jego przerwa jest tam, gdzie zaczepiony pierścień leży na wierzchu - dotknij go, a wyjdzie.",
