    game_weidefreunde: "Przyjaciele z łąki",
    home_weidefreunde_desc: "Gra karciano-kostkowa dla dzieci: rzucaj kostką ze zwierzętami i zbieraj na swojej łące pięć zwierząt z gospodarstwa – krowę, owcę, świnię, kurę i konia. Tylko obrazki, nie trzeba czytać, bez limitu czasu. Przeciwko komputerowi lub z maksymalnie czterema osobami na jednym urządzeniu.",
    weidefreunde_history_intro: "Gry z obrazkami zamiast liczb i z kartami do zbierania należą do pierwszych gier małych dzieci – ta łączy jedno i drugie.",
    quickrules_weidefreunde_1: "Rzuć kostką. Pokazuje zwierzę albo farmera.",
