    game_zoowurf: "Rzut w zoo",
    home_zoowurf_desc: "Gra w kości dla dzieci: rzucaj kostkami ze zwierzętami i uzupełnij kartę zwierzętami, które na niej widać – lwem, słoniem, żyrafą, małpą i pingwinem. Same obrazki, bez czytania, bez limitu czasu. Przeciw komputerowi lub w maksymalnie czterech osobach na jednym urządzeniu.",
    zoowurf_history_intro: "Rzucanie kostką i dobieranie obrazków to jedne z pierwszych gier małych dzieci – ta łączy jedno z drugim, ze zwierzętami z zoo.",
    quickrules_zoowurf_1: "Dotknij jednej z dwóch odkrytych kart. Pokazuje zwierzęta, które musisz wyrzucić.",
    quickrules_zoowurf_2: "Rzucaj kostkami do trzech razy. Kostki ze zwierzęciem z karty lub łapą zostają na karcie. Pozostałymi rzuć jeszcze raz.",
    quickrules_zoowurf_3: "Karta pełna: jest twoja i zaczyna się nowa runda. Niepełna: gra dalej następny gracz. Kto pierwszy ma cztery karty, wygrywa.",
