    zw_howto_1: "Dotknij jednej z dwóch odkrytych kart. Pokazuje zwierzęta, których potrzebujesz.",
    zw_howto_2: "Rzuć kostkami.",
    zw_howto_3: "Każda kostka ze zwierzęciem z karty trafia na kartę. Łapę kładziesz sam na wolne zwierzę według własnego wyboru.",
    zw_howto_4: "Rzuć pozostałymi kostkami jeszcze raz, do trzech razy. Pełna karta jest twoja; cztery karty wygrywają. Po ruchu komputera widzisz, co zrobił, i dotykasz Dalej.",
    game_klappenkasten: "Klappenkasten",
    home_klappenkasten_desc: "Tradycyjna gra w kości: rzuć dwiema kośćmi i zamknij ponumerowane klapki, które razem dają twój wynik. Gdy nic już nie pasuje, otwarte klapki liczą się przeciwko tobie – wygrywa najmniej punktów, a zamknięcie wszystkich klapek daje natychmiastowe zwycięstwo. Z komputerem lub do czterech osób na jednym urządzeniu.",
    kk_history_intro: "Tradycyjna gra w kości z rzędem ponumerowanych klapek, grana w gospodach i na statkach – gdzie i kiedy dokładnie powstała, nie jest pewne.",
    quickrules_klappenkasten_1: "Rzuć dwiema kośćmi i zamknij klapki, których numery razem dają wynik – jedną lub kilka.",
    quickrules_klappenkasten_2: "Rzucaj i zamykaj dalej. Gdy nic nie pasuje, numery otwartych klapek to twoje punkty.",
    quickrules_klappenkasten_3: "Wygrywa najmniej punktów; zamknięcie wszystkich klapek daje natychmiastowe zwycięstwo. „Cofnij” cofa zamknięcie.",
    kk_goal_line: "Cel: zamykaj klapki, które razem dają twój rzut. Mało otwartych klapek to mało punktów – wygrywa najmniej punktów.",
    kk_howto_1: "Rzuć dwiema kostkami.",
    kk_howto_2: "Zamknij klapki, które razem dają sumę: 8 to 3 i 5.",
    kk_howto_3: "Rzuć znowu i zamykaj kolejne klapki, dopóki jakieś pasują.",
    kk_howto_4: "Gdy nic nie pasuje, twoja tura się kończy. Otwarte klapki to twoje punkty: wygrywa najmniej.",
