    sw_again_hint: "Podwójna szóstka! Rzuć jeszcze raz.",
    game_steckwuerfeln: "Steckwürfeln",
    home_steckwuerfeln_desc: "Tradycyjna gra w kości i kołeczki z jedenastoma otworami o numerach od 2 do 12: rzuć dwiema kośćmi i wsuń kołek w otwór z sumą albo w dwa otwory z pojedynczymi kośćmi. Rzucaj dalej, dopóki coś pasuje – wolne otwory liczą się przeciwko tobie, wygrywa najmniej punktów. Warianty: podwójna szóstka jako joker albo wspólna plansza, na której odpada ten, kto nie może już wsunąć kołka.",
    sw_history_intro: "Mała tradycyjna gra w kości na planszy z ponumerowanymi otworami i kołkami – prosta, stara i do dziś sprzedawana jako drewniana gra kieszonkowa.",
    quickrules_steckwuerfeln_1: "Rzuć dwiema kośćmi. Wsuń kołek w otwór z sumą albo w dwa otwory z pojedynczymi kośćmi (2 i 4: otwór 6 albo otwory 2 i 4).",
    quickrules_steckwuerfeln_2: "Rzucaj i wsuwaj dalej. Gdy nic nie pasuje, numery wolnych otworów to twoje punkty.",
    quickrules_steckwuerfeln_3: "Wygrywa najmniej punktów. Podwójna szóstka to joker (rzuć jeszcze raz). „Cofnij” cofa kołek.",
