    game_sternjagd: "Sternjagd",
    home_sternjagd_desc: "Gra w pościg dla dwóch do czterech osób z jedną kością: wyrzucona liczba to dokładnie tyle kroków wzdłuż strzałek na planszy w kształcie gwiazdy. Kto zakończy ruch na przeciwniku, zabiera mu jedną z trzech gwiazd; przejście obok nic nie zmienia. Wygrywa ostatni gracz, który ma jeszcze gwiazdy.",
    sj_history_intro: "Gry w pościg z kością są tradycyjne w wielu kulturach; ta wersja ma własną planszę ze strzałkami.",
    quickrules_sternjagd_1: "Rzuć kością i przesuń się dokładnie o tyle kroków wzdłuż strzałek. Dotknij jednego z pól w ramce.",
    quickrules_sternjagd_2: "Zakończ ruch na przeciwniku, aby go złapać: traci gwiazdę i wraca do rogu. Przejście obok nic nie zmienia.",
