    game_kleeberg: "Kleeberg",
    home_kleeberg_desc: "Gra budowlana dla dwóch osób na piramidzie z okrągłych pól: na zmianę kładziecie serca albo koniczynki na wolne pola, ale tylko na dwa wypełnione pola. Trzy własne znaki w prostej linii wygrywają.",
    kb_history_intro: "Kleeberg to nowa gra z własnymi zasadami; opiera się na starym pomyśle ułożenia trzech w rzędzie.",
    quickrules_kleeberg_1: "Na zmianę: połóż serce lub koniczynkę na zakreślonym polu.",
    quickrules_kleeberg_2: "Buduj w górę: pole jest otwarte tylko wtedy, gdy oba pola pod nim są zapełnione.",
    quickrules_kleeberg_3: "Trzy własne znaki w prostej linii wygrywają. Jeśli piramida jest pełna i nikt nie ma linii, jest remis.",
    kb_move_hint: "Dotknij zakreślonego pola. Pola z przerywaną krawędzią nie są jeszcze otwarte.",
    kb_hearts: "Serca",
