    kb_field_name: "Rząd {r}, pole {c}",
    kb_field_move: "wolne, dotknij, aby tu budować",
    kb_field_locked: "jeszcze nie otwarte",
    kb_over_message: "Trzy w prostej linii wygrywają. Pełna piramida bez linii to remis.",
    kq_cards_label: "Karty",
    game_oddone: "Co tu nie pasuje?",
    home_oddone_desc: "Kilka kart jest podobnych pod jednym względem, oprócz jednej: dotknij tej, która nie pasuje. Rysunki z tej samej grupy albo kształty zgodne w jednej cesze. Sześć rund w grze, trzy poziomy, duże przyciski, bez limitu czasu, a gdy utkniesz – podpowiedź.",
    oddone_history_intro: "Znalezienie elementu, który nie pasuje, to klasyczne ćwiczenie w podręcznikach i testach myślenia – uczy porządkowania rzeczy według ich cech.",
    quickrules_oddone_1: "Kilka kart jest podobnych pod jednym względem, oprócz jednej.",
    quickrules_oddone_2: "Dotknij karty, która nie pasuje. Zła zostaje przekreślona – spróbuj innej.",
    quickrules_oddone_3: "Sześć rund to jedna gra. Nie ma limitu czasu, a podpowiedź zaznacza kartę, która nie pasuje.",
    od_win_title: "Wszystkie rundy gotowe!",
    msg_od_start: "Która nie pasuje? Dotknij jej.",
    msg_od_wrong: "Ta pasuje do pozostałych. Spróbuj innej.",
    msg_od_hint: "Podpowiedź: zaznaczona karta nie pasuje.",
    msg_t_od_won: "Wszystkie rundy gotowe! Błędy: {n}.",
    msg_t_od_won_modal: "Wszystkie rundy gotowe. Błędy: {n}.",
