    msg_t_od_aria_option: "Karta {n}",
    msg_t_od_aria_wrong: "Karta {n}, nieprawidłowa",
    msg_t_od_aria_right: "Karta {n}, prawidłowa",
    kq_shadows_label: "Cienie",
    family_picturelogic: "Zagadki obrazkowe",
    game_shadowmatch: "Czyj to cień?",
    home_shadowmatch_desc: "Obrazek i kilka czarnych cieni: który cień do niego pasuje? Sześć obrazków w grze, trzy poziomy – na trudnym ten sam obrazek pojawia się też obrócony lub odbity. Duże przyciski, bez limitu czasu, a gdy utkniesz – podpowiedź.",
    shadowmatch_history_intro: "Cienie od wieków obrysowuje się, wycina i wykorzystuje do zabawy – dopasowanie cienia do przedmiotu to małe ćwiczenie uważnego patrzenia.",
    quickrules_shadowmatch_1: "Na górze jest obrazek, a pod nim czarne cienie.",
    quickrules_shadowmatch_2: "Dotknij cienia, który ma dokładnie kontur obrazka. Zły zostaje przekreślony – spróbuj innego.",
    quickrules_shadowmatch_3: "Sześć obrazków to jedna gra. Nie ma limitu czasu, a podpowiedź zaznacza właściwy cień.",
    sm_win_title: "Wszystkie obrazki gotowe!",
    msg_sm_start: "Który cień pasuje do obrazka? Dotknij go.",
    msg_sm_wrong: "Ten cień nie pasuje. Spróbuj innego.",
