    kq_level_label: "Poziom",
    kq_answers_label: "Odpowiedzi",
    game_patternrow: "Dokończ wzór",
    home_patternrow_desc: "Rząd symboli układa się we wzór – który symbol będzie następny? Sześć rzędów w grze, trzy poziomy, kształty w czerni i bieli, duże przyciski odpowiedzi. Bez limitu czasu, a gdy utkniesz – podpowiedź.",
    patternrow_history_intro: "Rzędy powtarzających się znaków są tak stare jak garncarstwo i tkactwo, a ich kontynuowanie to ulubione zadanie w podręcznikach i testach.",
    quickrules_patternrow_1: "Rząd symboli powtarza się według wzoru; ostatnie miejsce jest puste.",
    quickrules_patternrow_2: "Dotknij symbolu, który pasuje na puste miejsce. Zły zostaje przekreślony – spróbuj innego.",
    quickrules_patternrow_3: "Sześć rzędów to jedna gra. Nie ma limitu czasu, a podpowiedź zaznacza właściwy symbol.",
    pr_win_title: "Wszystkie rzędy gotowe!",
    msg_pr_start: "Który symbol będzie następny? Dotknij odpowiedzi.",
    msg_pr_wrong: "To nie to. Spróbuj innego.",
