    game_catplaces: "Miejsca dla kotów",
    home_catplaces_desc: "W każdym wierszu, każdej kolumnie i każdym pokoju ma być dokładnie jeden kot - i dwa koty nie mogą się stykać, nawet rogiem. Łamigłówki logiczne w trzech rozmiarach, każda z jednym rozwiązaniem, do rozwiązania bez zgadywania.",
    kz_history_intro: "Zasady pochodzą z łamigłówki logicznej wymyślonej w 2003 roku na mistrzostwa świata w łamigłówkach w Holandii; tutaj miejsce gwiazdek zajmują śpiące koty.",
    quickrules_catplaces_1: "Postaw kota w każdym wierszu, każdej kolumnie i każdym pokoju (obszary otoczone grubymi liniami).",
    quickrules_catplaces_2: "Dwa koty nigdy się nie stykają - ani obok siebie, ani rogiem.",
    quickrules_catplaces_3: "Dotknij pola raz, aby postawić kota, drugi raz - kropkę (tu nie ma kota), trzeci raz - aby je wyczyścić. „Podpowiedź” wskazuje pole.",
