    game_rings: "Obracanie pierścieni",
    home_rings_desc: "Od trzech do pięciu pierścieni jeden w drugim, a na nich kształty. Obracaj pierścienie, aż każdy promień od środka pokaże ten sam kształt - na poziomie trudnym pierścień obraca też sąsiada. Z najmniejszą liczbą ruchów i przyciskiem podpowiedzi.",
    rg_history_intro: "Pierścienie ze znakami obracane względem siebie są stare: Leon Battista Alberti opisał w 1467 roku tarczę szyfrującą z dwóch obrotowych pierścieni. Łamigłówka tutaj powstała dla PaperGames.",
