    game_matches: "Zagadki z zapałkami",
    home_matches_desc: "Przełóż jedną lub dwie zapałki, aby błędne działanie stało się poprawne albo aby figura miała podaną liczbę kwadratów. 90 zagadek na trzech poziomach, każda sprawdzona przez komputer; dotknij zapałki, a potem wolnego miejsca - bez przeciągania.",
    mt_history_intro: "Zapałki stały się w XIX wieku czymś codziennym, a wkrótce materiałem na zagadki: książka Professora Hoffmanna Puzzles Old and New (1893) ma już rozdział zagadek z zapałkami.",
    quickrules_matches_1: "Dotknij zapałki, aby ją podnieść, a potem wolnego miejsca, aby ją tam położyć.",
