    game_tangram: "Tangram",
    home_tangram_desc: "Wypełnij kontur siedmioma klasycznymi elementami: trójkątami, kwadratem i równoległobokiem. 90 konturów na czterech poziomach, każdy z rozwiązaniem sprawdzonym przez komputer. W trybie „Tylko kontur” widzisz tylko zewnętrzną linię, a element zostaje tam, gdzie dotkniesz - trzeba próbować. Dotknij elementu, obróć go, dotknij miejsca - bez przeciągania.",
    tg_history_intro: "Siedem elementów wyciętych z kwadratu: łamigłówka pochodzi z Chin, gdzie w 1813 roku wydrukowano najstarszą zachowaną książkę na jej temat; od 1817 roku stała się szałem w Europie.",
    quickrules_tangram_1: "Wybierz element pod konturem, obróć go przyciskiem „Obróć o 45°” lub odbij, a potem dotknij miejsca, gdzie ma trafić.",
